    {
      "id": "A_R_FINISH",
      "name": "A_R_FINISH",
      "type": "ST",
      "body": "Raise := FALSE; ForkLeft := FALSE; ForkRight := FALSE; BeltRight := FALSE; RunIn := FALSE;"
    },
    {
      "id": "A_R_FINISH_ONCE",
      "name": "A_R_FINISH_ONCE",
      "type": "ST",
      "body": "IF Cell = 1 THEN Held1 := FALSE; Want1 := FALSE; ELSIF Cell = 2 THEN Held2 := FALSE; Want2 := FALSE; ELSE Held3 := FALSE; Want3 := FALSE; END_IF; Served := Served + 1;"
